/* 输入两个字符串；单独的 - 在平台中表示空字符串。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, i = 0, j = 0, m = 0, n = 0, ok = 0;
    n = readstr(a);
    m = readstr(b);
    /* 对每个合法起点重新检查全部字符，发现不等就将 ok 标成 0。 */
    ans = (-1);
    for (i = 0; i < ((n - m) + 1); i += 1)  {
        ok = 1;
        for (j = 0; j < m; j += 1)  {
            if (a[(i + j)] != b[j])  {
                ok = 0;
            }
        }
        if ((ok == 1) && (ans == (-1)))  {
            ans = i;
        }
    }
    /* 只在 ans 仍为 -1 时记录匹配，保证输出最早的零基起点。 */
    emit(ans);
    return 0;
}

