/* 输入两个字符串；单独的 - 在平台中表示空字符串。 */
use std::io:: {
    self, Read
}
;
fn mn(a: i32, b: i32) -> i32  {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32  {
    a.max(b)
}
fn emit(x: i32)  {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32)  {
    if n == 0  {
        print!("-");
    }
    for i in 0..n  {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader  {
    t: Vec<String>, p: usize,
}
impl Reader  {
    fn new() -> Self  {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self  {
            t: s.split_whitespace().map(String::from).collect(), p: 0,
        }
    }
    fn read(&mut self) -> i32  {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32  {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-"  {
            return 0;
        }
        for (i, c) in s.bytes().enumerate()  {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main()  {
    let mut reader = Reader::new();
    let mut a = vec![0i32;
    20000];
    let mut b = vec![0i32;
    20000];
    let mut d = vec![0i32;
    20000];
    let mut e = vec![0i32;
    20000];
    let mut ans: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut m: i32 = 0;
    let mut n: i32 = 0;
    let mut ok: i32 = 0;
    n = reader.readstr(&mut a);
    m = reader.readstr(&mut b);
    /* 对每个合法起点重新检查全部字符，发现不等就将 ok 标成 0。 */
    ans = (-1);
    i = 0;
    while i < ((n - m) + 1)  {
        ok = 1;
        j = 0;
        while j < m  {
            if (a[(i + j) as usize] != b[(j) as usize])  {
                ok = 0;
            }
            j += 1;
        }
        if ((ok == 1) && (ans == (-1)))  {
            ans = i;
        }
        i += 1;
    }
    /* 只在 ans 仍为 -1 时记录匹配，保证输出最早的零基起点。 */
    emit(ans);
}
